    // Launch-ready content (ToolContent.cs) replaces the draft Sections/Faqs above.
    public static readonly List<ToolDefinition> All = BaseList
        .Select(t => ToolContent.Overrides.TryGetValue(t.Slug, out var c) ? t with { Sections = c.Sections, Faqs = c.Faqs } : t)
        .ToList();

    // appsettings.json -> Tools:Hidden. Hidden tools return 404 and are left out of the home page, sitemap and related links.
    public static HashSet<string> Hidden { get; set; } = new();
    public static bool IsHidden(string slug) => Hidden.Contains(slug);
    public static IEnumerable<ToolDefinition> Visible => All.Where(t => !Hidden.Contains(t.Slug));

    public static ToolDefinition? Find(string slug) => All.FirstOrDefault(t => t.Slug == slug);
}
